import pyvista as pv
from pathlib import Path

# Path to the ADIOS2 VTX output folder generated by ns_code2.txt
vtx_file = Path("results/dfg2D-3-u.bp")

# Initialize PyVista reader
reader = pv.get_reader(str(vtx_file))

# Setup off-screen plotter for video rendering
plotter = pv.Plotter(off_screen=True)
plotter.open_movie("velocity_animation.mp4", framerate=30)

# Set camera angle (2D top view)
plotter.view_xy()

print("Generating animation frames...")
# Iterate through all saved time steps
for time_step in reader.time_values:
    reader.set_active_time_value(time_step)
    mesh = reader.read()[0]  # Extract mesh for current time step
    
    plotter.clear()
    plotter.add_mesh(
        mesh, 
        scalars="u_", 
        cmap="viridis", 
        scalar_bar_args={"title": f"Velocity Magnitude (t = {time_step:.2f}s)"}
    )
    plotter.write_frame()

plotter.close()
print("✅ Animation saved as velocity_animation.mp4")
